SELECT id, city, MIN(rating) OVER w_ordered AS running_min_rating, AVG(rating) OVER w_ordered AS running_avg_rating, COUNT(rating) OVER w_ordered AS running_count_rating, SUM(rating) OVER w_ordered AS running_sum_rating, ROW_NUMBER() OVER w_hist AS seq_no FROM suppliers WINDOW w_ordered AS (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_hist AS (PARTITION BY country ORDER BY rating, id);
